        <p><b>P</b> 暂停 / 继续</p>
        <p><b>R</b> 重新开始</p>
      </div>
    </div>

    <div class="board-wrap">
      <div class="board" :style="{ gridTemplateColumns: `repeat(${COLS}, 1fr)` }">
        <template v-for="(row, y) in displayGrid" :key="y">
          <div
