        </template>
      </div>

      <div v-if="!running && !gameOver" class="overlay">
        <h2>准备开始</h2>
        <p>按 <b>空格</b> 或点击下方按钮开始</p>
        <button class="btn" @click="startGame">开始游戏</button>
      </div>

      <div v-if="paused && !gameOver" class="overlay">
        <h2>已暂停</h2>
        <p>按 <b>P</b> 继续</p>
        <button class="btn" @click="togglePause">继续</button>
      </div>

      <div v-if="gameOver" class="overlay">
        <h2>游戏结束</h2>
        <p>本局得分：<b>{{ score }}</b></p>
        <button class="btn" @click="startGame">再来一局</button>
      </div>
    </div>

    <div class="panel right">
      <button class="btn" @click="startGame">重新开始</button>
      <button class="btn ghost" @click="togglePause" :disabled="!running || gameOver">
        {{ paused ? '继续' : '暂停' }}
      </button>
      <div class="tips">
        <p>消除 1 行 = 100 分</p>
        <p>消除 2 行 = 300 分</p>
        <p>消除 3 行 = 500 分</p>
        <p>消除 4 行 = 800 分</p>
        <p>分数 × 当前等级</p>
      </div>
    </div>
  </div>
</template>

